import { Dispatch } from "redux";

import {
  followAUser,
  unFollowAUser,
  getFollowingUsers,
} from "services/FavoriteService";
import { FavoriteParams } from "services/types/favorite";

import * as types from "./../types/favorite";

const favoriteLoading = (dispatch: Dispatch) => {
  dispatch({
    type: types.FAVORITE_LOADING,
    payload: true,
  });
};

export const favoriteByUsername =
  (params: FavoriteParams) => async (dispatch: Dispatch) => {
    try {
      await followAUser(params);
    } catch (error) {
      return Promise.reject(error);
    }
  };

export const unFavoriteByUsername =
  (params: FavoriteParams) => async (dispatch: Dispatch) => {
    try {
      await unFollowAUser(params);
    } catch (error) {
      return Promise.reject(error);
    }
  };

export const getFavoriteUsers = () => async (dispatch: Dispatch) => {
  try {
    favoriteLoading(dispatch);

    const { data } = await getFollowingUsers();

    dispatch({ type: types.FAVORITES, payload: data });
  } catch (error) {
    return Promise.reject(error);
  }
};
