import { memo, useEffect } from "react";

import Loading from "components/Loading";
import UserItem from "components/UserItem";
import { useTypedSelector, useTypedDispatch } from "stores/store";
import { getFavoriteUsers } from "stores/actions/favorite";
import { User } from "utils/types";
import { initialState } from "stores/favorite";

import * as S from "./styled";

const FavoritePage = () => {
  const dispatch = useTypedDispatch();

  const { isLoading, data }: initialState = useTypedSelector(
    (state) => state.favoriteState
  );

  useEffect(() => {
    dispatch(getFavoriteUsers());
  }, [dispatch]);

  if (isLoading) {
    return (
      <S.Wrap>
        <Loading />
      </S.Wrap>
    );
  }

  return (
    <S.Favorite>
      {data?.map((favorite: User) => (
        <UserItem key={favorite.login} user={favorite} defaultFavorite={true} />
      ))}
    </S.Favorite>
  );
};

export default memo(FavoritePage);
